        int num1 = 9, num2 = 2;
        System.out.println("الجمع: " + (num1 + num2));          // 11
        System.out.println("الطرح: " + (num1 - num2));          // 7
        System.out.println("الضرب: " + (num1 * num2));          // 18
        System.out.println("قسمة صحيحة: " + (num1 / num2));     // 4
