public class PrefixPostfixExample {
    public static void main(String[] args) {
        int x = 5;
        System.out.println("الأصلية: " + x);      // 5
        System.out.println("++x = " + (++x));     // 6
        System.out.println("بعد ++x: " + x);      // 6
        System.out.println("x++ = " + (x++));     // 6
        System.out.println("بعد x++: " + x);      // 7
        System.out.println("--x = " + (--x));     // 6
        System.out.println("بعد --x: " + x);      // 6
        System.out.println("x-- = " + (x--));     // 6
        System.out.println("النهائية: " + x);     // 5
    }
}

