public class Count1to10 {
    public static void main(String[] args) {
        // for
        for (int i = 1; i <= 10; i++) System.out.println(i);

        // while
        int j = 1;
        while (j <= 10) {
            System.out.println(j);
            j++;
        }

        // do..while
        int k = 1;
        do {
            System.out.println(k);
            k++;
        } while (k <= 10);
    }
}

public class Count10to1 {
    public static void main(String[] args) {
        // for
        for (int i = 10; i >= 1; i--) System.out.println(i);

        // while
        int j = 10;
        while (j >= 1) {
            System.out.println(j);
            j--;
        }

        // do..while
        int k = 10;
        do {
            System.out.println(k);
            k--;
        } while (k >= 1);
    }
}

